#!/usr/bin/env node
// PGlite migration check (T04): `npm run db:check`, no Docker needed.
//
// 1. Boots PGlite (Postgres 17 in WebAssembly) and loads the Supabase shim
//    (supabase/tests/shim/supabase_shim.psql: roles, auth.*, extensions, stubs).
// 2. Applies supabase/migrations/*.sql in order. PGlite has no PostGIS, pg_cron,
//    pg_net or pgmq, so their CREATE EXTENSION lines are skipped and
//    geography(...)/geometry(...) columns become bytea. Line numbers are kept.
// 3. Applies supabase/seed/*.sql (generated by T03/T03b) the same way.
// 4. Runs every pgTAP file under supabase/tests (*.sql) and checks the TAP:
//    a plan, as many results as planned, no `not ok`.
//
// A migration, seed or test that cannot run on PGlite (it calls ST_* or a real
// pg_cron job) puts `-- pglite: skip <reason>` in its first 20 lines. CI (ci-db)
// still runs it on Supabase Postgres 17, which is authoritative.
//
// Usage: node supabase/tools/pglite-check.mjs [--no-seed] [--no-tests] [--only <text>] [--verbose]
import { PGlite } from "@electric-sql/pglite";
import { btree_gist } from "@electric-sql/pglite/contrib/btree_gist";
import { pg_trgm } from "@electric-sql/pglite/contrib/pg_trgm";
import { pgcrypto } from "@electric-sql/pglite/contrib/pgcrypto";
import { pgtap } from "@electric-sql/pglite/pgtap";
import { vector } from "@electric-sql/pglite/vector";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const SUPABASE = join(ROOT, "supabase");
const SHIM = join(SUPABASE, "tests", "shim", "supabase_shim.psql");
const MIGRATIONS = join(SUPABASE, "migrations");
const SEED = join(SUPABASE, "seed");
const TESTS = join(SUPABASE, "tests");

// <prefix>HHMMSS_<task>_<what>.sql (WORK_BREAKDOWN §1 rule 3).
const MIGRATION_NAME = /^\d{14}_[a-z0-9]+_[a-z0-9_]+\.sql$/;
const UNAVAILABLE = ["postgis", "pg_cron", "pg_net", "pgmq"];
const SEARCH_PATH = 'set search_path to "$user", public, extensions';

const args = process.argv.slice(2);
const opt = {
  seed: !args.includes("--no-seed"),
  tests: !args.includes("--no-tests"),
  verbose: args.includes("--verbose"),
  only: args.includes("--only") ? args[args.indexOf("--only") + 1] : null,
};

const rel = (p) => relative(ROOT, p);
const sqlFiles = (dir) =>
  existsSync(dir)
    ? readdirSync(dir)
        .filter((f) => f.endsWith(".sql"))
        .sort()
        .map((f) => join(dir, f))
    : [];
const walkSql = (dir) => {
  if (!existsSync(dir)) return [];
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...walkSql(p));
    else if (name.endsWith(".sql")) out.push(p);
  }
  return out;
};
const skipReason = (sql) => {
  const head = sql.split("\n").slice(0, 20).join("\n");
  const m = head.match(/--\s*pglite:\s*skip\b(.*)/i);
  return m ? m[1].trim() || "marked pglite: skip" : null;
};
// Replace a match with something of the same line count, so error lines still point at the source.
const keepLines = (match, replacement) =>
  replacement + "\n".repeat((match.match(/\n/g) ?? []).length);

function rewriteForPglite(sql) {
  const skipped = new Set();
  let out = sql.replace(
    /create\s+extension\s+(?:if\s+not\s+exists\s+)?"?([a-z_]+)"?[^;]*;/gi,
    (m, name) => {
      if (!UNAVAILABLE.includes(name.toLowerCase())) return m;
      skipped.add(name.toLowerCase());
      return keepLines(m, `/* pglite: skipped extension ${name} */;`);
    },
  );
  out = out.replace(
    /\b(?:extensions\.)?(?:geography|geometry)\s*\(\s*[a-z]+\s*(?:,\s*\d+\s*)?\)/gi,
    (m) => keepLines(m, "bytea"),
  );
  out = out.replace(/::\s*(?:extensions\.)?(?:geography|geometry)\b/gi, "::bytea");
  return { sql: out, skipped: [...skipped] };
}

function lineOf(sql, position) {
  const pos = Number(position);
  if (!Number.isFinite(pos) || pos < 1) return null;
  return sql.slice(0, pos - 1).split("\n").length;
}

function describeError(e, file, sql) {
  const line = lineOf(sql, e.position);
  const where = line ? `${rel(file)}:${line}` : rel(file);
  const bits = [`${where}: ${e.code ? `[${e.code}] ` : ""}${e.message}`];
  if (e.detail) bits.push(`  detail: ${e.detail}`);
  if (e.hint) bits.push(`  hint: ${e.hint}`);
  if (e.where) bits.push(`  where: ${e.where}`);
  if (line) bits.push(`  > ${sql.split("\n")[line - 1]?.trim()}`);
  return bits.join("\n");
}

function tapLines(results) {
  const lines = [];
  for (const r of results) {
    if (!r.fields || r.fields.length !== 1) continue;
    const field = r.fields[0].name;
    for (const row of r.rows) {
      const v = row[field];
      if (typeof v === "string") lines.push(...v.split("\n"));
    }
  }
  return lines.filter((l) => /^(?:not ok|ok)\b|^1\.\.\d+|^\s*#/.test(l));
}

function judgeTap(lines) {
  const planLine = lines.find((l) => /^1\.\.\d+/.test(l));
  const planned = planLine ? Number(planLine.match(/^1\.\.(\d+)/)[1]) : null;
  const results = lines.filter((l) => /^(?:not ok|ok) \d+/.test(l));
  const failed = results.filter((l) => l.startsWith("not ok") && !/#\s*TODO/i.test(l));
  const problems = [];
  if (planned === null) problems.push("no plan (call select plan(n) or no_plan())");
  else if (planned !== results.length) problems.push(`planned ${planned}, ran ${results.length}`);
  if (failed.length) problems.push(`${failed.length} failed`);
  return { planned, ran: results.length, failed, problems };
}

async function main() {
  const t0 = Date.now();
  const db = new PGlite({ extensions: { btree_gist, pg_trgm, pgcrypto, pgtap, vector } });
  const { rows } = await db.query("select version() as v");
  console.log(`PGlite migration check (${rows[0].v.split(" on ")[0]}, no Docker)`);

  let failures = 0;
  const fail = (msg) => {
    failures += 1;
    console.log(`FAIL ${msg}`);
  };

  // 1. Shim.
  const shim = readFileSync(SHIM, "utf8");
  try {
    await db.exec(shim);
    console.log(`  shim     ${rel(SHIM)}`);
  } catch (e) {
    fail(describeError(e, SHIM, shim));
    process.exit(1);
  }

  // 2. Migrations.
  const migrations = sqlFiles(MIGRATIONS);
  for (const file of migrations) {
    const name = file.split("/").pop();
    if (!MIGRATION_NAME.test(name)) {
      fail(
        `${rel(file)}: name must be <prefix>HHMMSS_<task>_<what>.sql (WORK_BREAKDOWN §1 rule 3)`,
      );
      continue;
    }
    const raw = readFileSync(file, "utf8");
    const reason = skipReason(raw);
    if (reason) {
      console.log(`  skip     ${name}  (${reason})`);
      continue;
    }
    const { sql, skipped } = rewriteForPglite(raw);
    try {
      await db.exec(sql);
      console.log(
        `  migrate  ${name}${skipped.length ? `  (no ${skipped.join(", ")} in PGlite)` : ""}`,
      );
    } catch (e) {
      fail(describeError(e, file, sql));
      console.log("Stopping: later migrations depend on this one.");
      process.exit(1);
    }
  }

  // 3. Seed.
  const seeds = opt.seed ? sqlFiles(SEED) : [];
  if (!opt.seed) console.log("  seed     skipped (--no-seed)");
  else if (!seeds.length) console.log("  seed     none yet (T03 generates supabase/seed/*.sql)");
  for (const file of seeds) {
    const raw = readFileSync(file, "utf8");
    const reason = skipReason(raw);
    if (reason) {
      console.log(`  skip     ${rel(file)}  (${reason})`);
      continue;
    }
    const { sql } = rewriteForPglite(raw);
    try {
      await db.exec(sql);
      console.log(`  seed     ${rel(file)}`);
    } catch (e) {
      fail(describeError(e, file, sql));
      await db.exec("rollback").catch(() => {});
    }
  }

  // 4. pgTAP.
  let assertions = 0;
  let ranTests = 0;
  let skippedTests = 0;
  const tests = opt.tests
    ? walkSql(TESTS).filter((f) => !opt.only || rel(f).includes(opt.only))
    : [];
  if (!opt.tests) console.log("  tests    skipped (--no-tests)");
  for (const file of tests) {
    const raw = readFileSync(file, "utf8");
    const reason = skipReason(raw);
    if (reason) {
      skippedTests += 1;
      console.log(`  skip     ${rel(file)}  (${reason})`);
      continue;
    }
    const { sql } = rewriteForPglite(raw);
    let lines = [];
    let error = null;
    try {
      lines = tapLines(await db.exec(sql));
    } catch (e) {
      error = e;
    }
    // Leave a clean session for the next file.
    await db.exec("rollback").catch(() => {});
    await db.exec(`reset role; reset all; ${SEARCH_PATH};`).catch(() => {});

    ranTests += 1;
    const verdict = judgeTap(lines);
    assertions += verdict.ran;
    if (error) {
      fail(describeError(error, file, sql));
      if (lines.length) console.log(lines.map((l) => `    ${l}`).join("\n"));
    } else if (verdict.problems.length) {
      fail(`${rel(file)}: ${verdict.problems.join("; ")}`);
      console.log(
        lines
          .filter((l) => opt.verbose || l.startsWith("not ok") || l.startsWith("#"))
          .map((l) => `    ${l}`)
          .join("\n"),
      );
    } else {
      console.log(`  test     ${rel(file)}  ${verdict.ran}/${verdict.planned}`);
      if (opt.verbose) console.log(lines.map((l) => `    ${l}`).join("\n"));
    }
  }

  await db.close();
  const secs = ((Date.now() - t0) / 1000).toFixed(1);
  const summary = `${migrations.length} migrations, ${seeds.length} seed files, ${ranTests} test files (${assertions} assertions), ${skippedTests} skipped, ${secs}s`;
  if (failures) {
    console.log(`\ndb:check FAILED (${failures}): ${summary}`);
    process.exit(1);
  }
  console.log(`\ndb:check OK: ${summary}. CI (ci-db) reruns all of it on Supabase Postgres 17.`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
